```python
def frequences(texte):
    d = {}
    for c in texte:
        if c in d:
            d[c] = d[c] + 1
        else:
            d[c] = 1
    return d
```

```python
def plus_frequent(texte):
    d = frequences(texte)
    meilleur = None
    for c in d:
        if meilleur is None or d[c] > d[meilleur]:
            meilleur = c
    return meilleur
```
